/**
 * NextAuth.js v5 route handler.
 *
 * Exports the GET and POST handlers generated by `NextAuth(authConfig)` so
 * that all auth flows (AniList OAuth, Discord OAuth, session management) are
 * served from `app/api/auth/[...nextauth]`.
 */

import { handlers } from "@/lib/auth";

export const { GET, POST } = handlers;